  PanelText_UI_Events_Panel_Arachne_StageGroup_Text_C_Introduction_Content = {
    Text = "Las luces se encienden. Los aplausos se apagan. El público espera con anticipación.\nEs hora de subir al escenario, mis queridos niños. Adelante—actúen, desgarren sus propias almas y vendan sus secretos más profundos. Tomen sus heridas más devastadoras y transfórmenlas en dulces para el deleite del público. Regodéense con avidez en ese único haz de luz encendido solo para ustedes, hasta que el telón caiga para sepultarlos tanto a ustedes como a su audiencia.\n\nEste es el escenario para el que estaban destinados—¡asciendan! No tengan miedo; no hay necesidad de pánico escénico."
  },
