  PanelText_UI_Events_Panel_Caraboo_StageGroup_Text_C_Introduction_Content = {
    Text = "♪~~♫~~♪~~♫~~♪~~♫~~\nBajo la montaña nevada, todo guía la recuerda y todo niño aún la canta. Ella es la voluntad de la imponente montaña hecha carne, ella es la misericordiosa diosa Umapati. Su poder divino yace disperso por el mundo mortal; sus tesoros no pueden hallarse. Están tan cerca que se pueden tocar; no dejan rastro alguno. \nRenuncia a algo. Afférrate a algo. Aquel cuyo corazón sea falso ante la verdadera forma de la diosa quedará enterrado en la montaña nevada para siempre, junto a la montaña que murió."
  },
