  },
  PanelText_UI_Events_Panel_Castor_StageGroup_Text_C_Introduction_Content = {
    Text = "La vida de un ave está destinada a ser una vida de libertad. Debes ver el momento en que rompe el cascarón, recuperando la libertad de vivir de las garras de la muerte. Debes ver el momento en que aprende a volar, recuperando la libertad de sobrevivir por sí misma de su cálido nido. Si hoy arrojas la llave de la libertad en el abismo de la muerte, sin duda saltará sin dudarlo, eligiendo enfrentar la tormenta de la muerte entre la estrecha vida y la infinita libertad."
  },
