  PanelText_UI_Events_Panel_Clementine_StageGroup_Text_C_Introduction_Content = {
    Text = "Desde entonces, no ha derramado ni una sola lágrima.  \nVagando sola, deambulando por un mundo lleno de seres extraños.  \nUn gran plan está a punto de comenzar, como su última despedida.  \nElla es la psicóloga más exitosa, este es su tratamiento más exitioso."
