  PanelText_UI_Events_Panel_Daffodil_StageGroup_Text_C_Introduction_Content = {
    Text = "En este pequeño pueblo costero, hay una bulliciosa calle comercial. El comercio marítimo ha traído innumerables productos modernos, y siempre que pagues suficiente con leones de Leo, podrás obtener mercancías satisfactorias. \n Excepto por una pequeña tienda en la esquina, que está llena de antigüedades mágicas. Entre el humo que sale de la pipa, la dueña, con su sombrero de ala ancha, te mostrará lentamente una sonrisa. \n \"Bienvenido a la tienda de alivio de preocupaciones, aquí podemos satisfacer todas tus necesidades, siempre que pagues una recompensa justa...\" \n \"Por supuesto, por supuesto, los precios son justos y no engañamos a nadie.\""
  },
