  PanelText_UI_Events_Panel_KathiguRa_StageGroup_Text_C_Introduction_Content = {
    Text = "Ella se erige una vez más sobre la Tierra, la venganza que consume todo llega como se esperaba. \n\n Esa es la caza que nunca cesa, ese es el ardor del Señor de la Explosión Ardiente. \n\n Ella recorrerá cada rincón, cazando a todos aquellos que han hecho pactos con la muerte. \n\n Huye, huye, escapa a la oscuridad más profunda, escapa a un lugar donde crees que no serás encontrado. \n\n Aunque esto carezca de sentido, porque Él finalmente pisará cada mundo. \n\n Él cazará hasta que todo se convierta en cenizas."
  },
