    Text = "Cielo~despejado~mar~tranquilo~\nMosk~amigo~Bola de carbón~¡zarpar!\nTormenta, no temer, relámpago, no temer, Mosk, amigo, Bola de carbón~\n¡Por la libertad, hay que·partir"
