  PanelText_UI_Events_Panel_Mouchette_StageGroup_Text_C_Introduction_Content = {
    Text = "De repente, un día, te das cuenta de que has cambiado. \n Nadie se da cuenta de esto, porque tienes el mismo comportamiento, el mismo rostro de belleza deslumbrante. \n Pero tú sabes muy bien que ese corazón que solía ser rojo brillante, ahora está cubierto por una máscara hecha de niebla. \n \"Si puedo seguir disfrazándome, ¿seguiré siendo el mismo yo de antes?\"\n Afortunadamente, esta pregunta no se queda en tu mente más de un segundo, porque antes de quitar esa máscara, nadie conoce tus verdaderos pensamientos. \n \"Entonces, ¡vamos a partir!~\""
  },
