  PanelText_UI_Events_Panel_OriDoll_StageGroup_Text_C_Introduction_Content = {
    Text = "Ella miraba la gran puerta al final del mundo, y sin dudarlo dio un paso adelante. \n ¡Clic! Giró la manija, ansiosa por mirar detrás de la puerta. \n Sin embargo, detrás de la puerta no había nada; pisó en falso y cayó en el vacío. \n Ya debería haberlo sabido, que un regalo que llega de manera tan directa siempre tiene un alto precio."
