    Text = "Lo que prometió el dios está cerca. \n Después de miles de años de espera, la alegre culminación está a punto de llegar, la tierra prometida se elevará del mar. \n Los dioses resucitarán del pecho de la Madre divina, y al final de los siete días, un nuevo mundo descenderá."
