  PanelText_UI_Events_Panel_Pickman_StageGroup_Text_C_Introduction_Content = {
    Text = "Entre la razón y el colapso, el engañoso lienzo se despliega lentamente. \n Las ilusiones que desprecias crean colores magníficos, \n el descontrol que temes conforma la forma de la lealtad. \n Aquí, la locura es el instinto del arte, es la raíz del mundo, \n es la única verdad que no miente."
