  PanelText_UI_Events_Panel_Pontos_StageGroup_Text_C_Introduction_Content = {
    Text = "Cuando la siniestra luz blanca vuelve a traspasar las ventanas de la Casa, él ya te ha enviado su invitación.\nAcoger, engullir, envolver, abarrotar... \nResponde al Llamar desde las profundidades del océano, únete a esta cacería sin fin; tu pasado, tu ser, todo ha dejado de importar."
