  PanelText_UI_Events_Panel_Saya_StageGroup_Text_C_Introduction_Content = {
    Text = "¿Ciencia? Sin importancia. ¿Ética? Sin importancia. ¿Moralidad? Sin importancia. \nVida, muerte, esperanza, desesperación... al final, en un cuaderno en el sótano, la misma demostración está escrita por dos manos diferentes. \nDicen: <Italic:\"Mira: el amor es el único tema eterno.\">"
