  PanelText_UI_Events_Panel_Sorel_StageGroup_Text_C_Introduction_Content = {
    Text = "Años después, un biógrafo llamó a su puerta una tarde.\nHablaron mucho ese día, desde ágatas hasta mansiones con rosas marchitas...\nAhora, el escritor ha compilado esas palabras dispersas en un libro, dedicado a todos ustedes"
