  PanelText_UI_Events_Panel_StElmosFire_StageGroup_Text_C_Introduction_Content = {
    Text = "El viejo sextante determina el ángulo de las estrellas, las antiguas cartas marinas trazan las rutas esperadas, la desgastada brújula decide la dirección a seguir...\nIncluso en las profundidades heladas del Mar Negro, hay exploradores que, con cobre y hierro comunes, guían a todos por el camino. \nQue todos los guías no caigan en la confusión."
